-- Databricks SQL
-- 1. Create a catalog (top level of the namespace)
CREATE CATALOG IF NOT EXISTS main;

-- 2. Create a schema (database) inside the catalog
CREATE SCHEMA IF NOT EXISTS main.sales
  COMMENT "Sales domain tables";

-- 3. Create a managed Delta table
CREATE TABLE IF NOT EXISTS main.sales.orders (
  order_id   BIGINT,
  customer_id BIGINT,
  amount     DECIMAL(10,2),
  order_ts   TIMESTAMP
)
USING DELTA
COMMENT "Cleaned customer orders";

-- 4. Grant least-privilege access to the analytics group
GRANT USE CATALOG ON CATALOG main TO `analysts`;
GRANT USE SCHEMA ON SCHEMA main.sales TO `analysts`;
GRANT SELECT ON TABLE main.sales.orders TO `analysts`;

# job.json - a simple notebook job on an autoscaling job cluster
{
  "name": "daily-orders-etl",
  "tasks": [
    {
      "task_key": "transform_orders",
      "notebook_task": {
        "notebook_path": "/Repos/data-eng/etl/transform_orders"
      },
      "new_cluster": {
        "spark_version": "14.3.x-scala2.12",
        "node_type_id": "i3.xlarge",
        "autoscale": { "min_workers": 2, "max_workers": 8 }
      }
    }
  ],
  "schedule": {
    "quartz_cron_expression": "0 0 6 * * ?",
    "timezone_id": "UTC"
  }
}

# Create the job from the definition, then run it now
databricks jobs create --json @job.json
databricks jobs run-now --job-id 1234
